import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.select.Elements;
import org.jsoup.select.Selector;
import org.jsoup.select.QueryParser;
import org.jsoup.select.Evaluator;

public class Probe {
    static int pass = 0, fail = 0;

    static void check(String name, String html, String css, String expected) {
        Document doc = Jsoup.parse(html);
        String got;
        try {
            Elements els = doc.select(css);
            StringBuilder sb = new StringBuilder();
            for (Element e : els) {
                if (sb.length() > 0) sb.append(",");
                String id = e.id();
                sb.append(id.isEmpty() ? e.tagName() : id);
            }
            got = sb.toString();
        } catch (Exception ex) {
            got = "THROW:" + ex.getClass().getSimpleName() + ":" + ex.getMessage();
        }
        if (got.equals(expected)) { pass++; }
        else { fail++; System.out.println("FAIL " + name + "\n  css=" + css + "\n  expected=" + expected + "\n  got     =" + got); }
    }

    static void checkThrows(String name, String css) {
        try {
            Document doc = Jsoup.parse("<div id=a><p id=p>x</p></div>");
            doc.select(css);
            fail++; System.out.println("FAIL " + name + ": expected throw for " + css);
        } catch (Selector.SelectorParseException e) {
            pass++;
        } catch (Exception e) {
            fail++; System.out.println("FAIL " + name + ": wrong exception " + e.getClass().getName() + " for " + css);
        }
    }

    public static void main(String[] args) {
        // --- basic descendant / child scoping ---
        String h1 = "<div id=a><div id=b><span id=s></span></div></div>";
        check("desc", h1, "div:has(span)", "a,b");
        check("child1", h1, "div:has(> span)", "b");
        check("child2", h1, "#a:has(> #b)", "a");
        check("child3", h1, "#a:has(> #s)", "");
        check("self-not-descendant", h1, "div:has(div)", "a");
        check("span-self", h1, "span:has(span)", "");

        // --- sibling scoping ---
        String h2 = "<ul id=u><li id=l1><p id=p1></p></li><li id=l2></li><li id=l3><p id=p3></p></li></ul>";
        check("adj-sib-desc", h2, "li:has(+ li p)", "l2");
