import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.select.Elements;
import org.jsoup.select.Selector;
import org.jsoup.select.Evaluator;
import org.jsoup.select.NodeEvaluator;
import org.jsoup.nodes.Node;
import org.jsoup.nodes.Comment;
import org.jsoup.nodes.TextNode;

import java.util.concurrent.atomic.AtomicInteger;

public class Probe2 {
    static int pass = 0, fail = 0;

    static String ids(Elements els) {
        StringBuilder sb = new StringBuilder();
        for (Element e : els) { if (sb.length() > 0) sb.append(","); sb.append(e.id().isEmpty() ? e.tagName() : e.id()); }
        return sb.toString();
    }

    static void expect(String name, Document doc, String css, String expected) {
        String got = ids(doc.select(css));
        if (got.equals(expected)) pass++;
        else { fail++; System.out.println("FAIL " + name + " css=" + css + " expected=" + expected + " got=" + got); }
    }

    static void expect(String name, String html, String css, String expected) {
        expect(name, Jsoup.parse(html), css, expected);
    }

    static void expectThrows(String name, String css) {
        try {
            Jsoup.parse("<div id=a><p>x</p></div>").select(css);
            fail++; System.out.println("FAIL " + name + ": no throw: " + css);
        } catch (Selector.SelectorParseException e) { pass++;
        } catch (Exception e) { fail++; System.out.println("FAIL " + name + ": " + e.getClass().getSimpleName() + " " + css); }
    }

    public static void main(String[] args) {
        // mixed sibling + descendant branches within one :has
        String h = "<ul><li id=a></li><li id=b><a id=ba></a></li><li id=c><span id=cs></span></li><li id=d></li></ul>";
        expect("mixed-1", h, "li:has(+ li, a)", "a,b");
        expect("mixed-2", h, "li:has(> a, + li span)", "b");
        expect("mixed-3", h, "li:has(~ li a, + li)", "a,b,c");
        expect("ws-branches", h, "li:has( a , span )", "a,b,c");

        // nested has with sibling axis on inner
        String h2 = "<div id=d><p id=p></p><section id=s><a id=a></a></section></div>";
        expect("nested-sib", h2, "div:has(section:has(+ p))", ""); // p is BEFORE section
        expect("nested-sib2", "<div id=d><section id=s></section><p id=p></p></div>",
            "div:has(section:has(+ p))", "d");
        expect("nested-sib3", "<div id=d><section id=s><b></b></section><p id=p></p></div>",
            "div:has(section:has(b):has(+ p))", "d");
        // inner sibling axis must not be driven by outer candidate's siblings
        expect("nested-sib-isolation",
            "<div id=d><section id=s></section></div><p id=p></p>",
            "div:has(section:has(+ p))", "");

        // :is inside :has
        expect("is-in-has", "<div id=d><p></p><span></span></div>", "div:has(:is(p, span))", "d");
        expect("is-chain", "<div id=d><p></p><a></a></div>", "div:has(:is(p) + a)", "d");
        expect("is-sib-anchor",
            "<div id=d></div><p id=p></p>", "div:has(:is(div) + p)", "");

        // compound has AND
        expect("and-has", "<div id=d><a></a><b></b></div><div id=e><a></a></div>",
            "div:has(a):has(b)", "d");

        // quoted attr inside has
        expect("quoted-in-has",
