import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.select.Elements;
import org.jsoup.select.Selector;
import org.jsoup.select.Evaluator;
import org.jsoup.select.CombiningEvaluator;

import java.util.stream.IntStream;

public class Probe3 {
    static int pass = 0, fail = 0;

    static String ids(Elements els) {
        StringBuilder sb = new StringBuilder();
        for (Element e : els) { if (sb.length() > 0) sb.append(","); sb.append(e.id().isEmpty() ? e.tagName() : e.id()); }
        return sb.toString();
    }

    static void sel(Document doc, String css, String... expected) {
        String exp = String.join(",", expected);
        String got = ids(doc.select(css));
        if (got.equals(exp)) pass++;
        else fail++ == 0;
        if (!got.equals(exp)) System.out.println("FAIL [" + css + "] expected=" + exp + " got=" + got);
    }

    public static void main(String[] args) {
        // hasDirectChildren
        Document doc = Jsoup.parse("<div id=empty></div>"
            + "<div id=child><a href=x></a></div>"
            + "<div id=deep><section><a href=x></a></section></div>");
        sel(doc, "div:has(> a[href])", "child");
        sel(doc, "div:has(> missing)");
        sel(doc, "div:has(> section a)", "deep");
        sel(doc, "div:has(> section > a)", "deep");

        // hasDirectChildAlternatives
        doc = Jsoup.parse("<div id=early><a href=x></a><span></span></div>"
            + "<div id=late><section></section><span></span></div>"
            + "<div id=deep><section><span></span></section></div>");
        sel(doc, "div:has(> a[href], > span)", "early", "late");
        sel(doc, "div:has(> a[href], span)", "early", "late", "deep");

        // hasDirectChildWithNestedHas
        doc = Jsoup.parse("<article id=nested><div><section><a></a></section></div></article>"
            + "<article id=span><span></span></article>"
            + "<article id=deep><section><span></span></section></article>");
        sel(doc, "article:has(> div:has(a), > span)", "nested", "span");

        // hasDirectChildNodes
        doc = Jsoup.parse("<article id=span><span></span></article>"
            + "<article id=comment>text<!--direct--></article>"
            + "<article id=deepComment><section><!--deep--></section></article>");
        sel(doc, "article:has(> ::comment)", "comment");
        sel(doc, "article:has(> span, > ::comment)", "span", "comment");
        sel(doc, "article:has(> ::comment, section ::comment)", "comment", "deepComment");

        // hasSiblingAlternatives
        for (String query : new String[]{"#a:has(+ div, > missing)", "#a:has(> missing, + div)"}) {
