import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.select.Selector;
import org.jsoup.select.Evaluator;
import java.util.stream.IntStream;

public class Probe7 {
    public static void main(String[] a) {
        // 1. parallel reuse of compiled has evaluator across threads/docs
        Evaluator[] evals = {
            Selector.evaluatorOf("div:has(+ div span, > a)"),
            Selector.evaluatorOf("article:has(> h1, ~ ::comment, + p)"),
            Selector.evaluatorOf("div:has(p:has(> b + i), ::comment)"),
        };
        IntStream.range(0, 16).parallel().forEach(i -> {
            Document doc = Jsoup.parse("<div id=a></div><div><span></span></div><div id=b><a></a></div>");
            String expect = doc.select("div:has(+ div span, > a)").toString();
            for (Evaluator e : evals) {
                doc.select(e);
                doc.selectFirst(e);
            }
            if (!doc.select(evals[0]).toString().equals(expect))
                throw new AssertionError("parallel mismatch");
        });
        System.out.println("parallel OK");

        // 2. round trip equivalence, many queries
        String html = "<div id=1><p id=p1><b>B</b><i>I</i></p><!--c--></div><div id=2><h1>H</h1><h2>X</h2></div>";
        Document d1 = Jsoup.parse(html);
        Document d2 = Jsoup.parse(d1.html());
        String[] qs = {
            "div:has(> p, > h1)", "div:has(p:has(b + i))", ":has(::comment)", "div:has(~ div)",
            "p:has(+ i)", "div:has(h1 ~ h2), div:has(> p)", "*:has(*)", "div:has(:scope + div)",
            "div:has(> ::comment)", "div:has(p ::text)"
        };
        for (String q : qs) {
            String r1 = path(d1, q);
            String r2 = path(d2, q);
            if (!r1.equals(r2)) throw new AssertionError("roundtrip q=" + q + "\n" + r1 + "\n" + r2);
        }
        System.out.println("roundtrip OK");

        // 3. empty/no-match docs
        Document empty = Jsoup.parse("");
        for (String q : qs) {
            if (!empty.body().select(q).isEmpty()) throw new AssertionError("empty doc: " + q);
        }
        Document nomatch = Jsoup.parse("<div></div><span></span>");
        if (!nomatch.select("div:has(p, a), :has(::comment)").isEmpty())
            throw new AssertionError("nomatch");
        System.out.println("empty/nomatch OK");

        // 4. no mutation across node-iterator pool reuse incl nested has
        Document d = Jsoup.parse(html);
        String before = d.html();
        for (int i = 0; i < 100; i++) {
            d.select("div:has(p:has(b:has(+ i), ~ ::comment), ::comment, + div)");
        }
        if (!before.equals(d.html())) throw new AssertionError("mutation");
        System.out.println("no-mutation OK");
    }
    static String path(Document d, String q) {
        StringBuilder sb = new StringBuilder();
        d.select(q).forEach(e -> sb.append(e.cssSelector()).append("|"));
        return sb.toString();
    }
}
