        ids("gap +div>comment", "<div id=a></div>x<div><!--inside--></div>", "#a:has(+ div > ::comment)");
        ids("gap +div comment", "<div id=a></div>x<div><span><!--inside--></span></div>", "#a:has(+ div span)");
