        ids("sibtree internal+", "<div id=a></div><div><h1></h1><!--c--><b></b></div>", "#a:has(+ div h1 + ::comment + b)", "a");
        ids("sibtree internal+ block", "<div id=a></div><div><h1></h1>x<!--c--><b></b></div>", "#a:has(+ div h1 + ::comment + b)");
        // text then immediate comment semantics: local strict => blocked
        ids("text then comment +", "<div id=a></div>text<!--c-->", "#a:has(+ ::comment)");
