import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.select.Elements;

public class Probe8 {
    static int fails = 0;
    static void ids(String label, String html, String q, String... want) {
        Document d = Jsoup.parse(html);
        String got = d.select(q).eachAttr("id").toString();
        String w = java.util.Arrays.toString(want);
        if (!got.equals(w)) { fails++; System.out.println("FAIL " + label + " q=" + q + " got=" + got + " want=" + w); }
        else System.out.println("OK   " + label);
    }
    public static void main(String[] a) {
        // not(:has()) layer scoping
        ids("not has", "<div id=1><p></p></div><div id=2><a></a></div>", "div:not(:has(p))", "2");
        ids("not has nested", "<div id=1><p><a></a></p></div><div id=2><p></p></div>", "div:has(p:not(:has(a)))", "2");
        // deep nesting
        ids("deep nested >", "<div id=x><section><article><a></a></article></section></div>",
            "div:has(section:has(article:has(> a)))", "x");
        ids("deep nested bare", "<div id=x><section><article><a></a></article></section></div>",
            "div:has(section:has(article a))", "x");
        // dedupe: same candidate hits several branches & descendants
        Document d = Jsoup.parse("<div id=d><p id=p1><a></a></p><p id=p2><a></a></p></div>");
        Elements r = d.select("div:has(p a, p:has(a), p > a)");
        if (r.size() != 1 || !r.first().id().equals("d")) { fails++; System.out.println("FAIL dedupe size=" + r.size()); }
        else System.out.println("OK   dedupe");
        // candidate and its descendant both match, document order
        ids("ancestor+desc order", "<section id=s><div id=d1><p></p></div><div id=d2></div></section>",
            "*:has(p), div:has(> p)", "s", "d1");
        // > ::text direct child leaf
        ids("> ::text", "<article id=a>hello</article><article id=b><p>x</p></article>",
            "article:has(> ::text)", "a");
        // sibling mixed: node then element branches, same anchor
        ids("mixed sib branches", "<article id=a></article>x<p></p>",
            "article:has(+ ::text, + p)", "a");
        // ~ over leaves with descendants inside later sibling
        ids("tilde deep leaf", "<article id=a></article><p></p><div><b><!--c--></b></div>",
            "article:has(~ div ::comment)", "a");
        // + cannot skip gap element even for ~ chain? ~ can, + cannot
        ids("plus blocks on gap elem for leaf chain", "<article id=a></article><p></p><!--c-->",
            "article:has(+ ::comment)");
        // wildcard sibling
        ids("wildcard +", "<a id=a></a><b></b>", "a:has(+ *)", "a");
        // negation inside has branch
        ids("not inside has", "<div id=x><p class=z></p></div><div id=y><p></p></div>",
            "div:has(p:not(.z))", "y");
        System.out.println(fails == 0 ? "ALL PASS" : fails + " FAILURES");
        System.exit(fails==0?0:1);
    }
}
