        doc = Jsoup.parse("<div id=early><a href=x></a><span></span></div>"
            + "<div id=late><section></section><span></span></div>"
            + "<div id=deep><section><span></span></section></div>");
        sel(doc, "div:has(> a[href], > span)", "early", "late");
        sel(doc, "div:has(> a[href], span)", "early", "late", "deep");

        // hasDirectChildWithNestedHas
        doc = Jsoup.parse("<article id=nested><div><section><a></a></section></div></article>"
            + "<article id=span><span></span></article>"
            + "<article id=deep><section><span></span></section></article>");
        sel(doc, "article:has(> div:has(a), > span)", "nested", "span");

        // hasDirectChildNodes
        doc = Jsoup.parse("<article id=span><span></span></article>"
            + "<article id=comment>text<!--direct--></article>"
            + "<article id=deepComment><section><!--deep--></section></article>");
        sel(doc, "article:has(> ::comment)", "comment");
        sel(doc, "article:has(> span, > ::comment)", "span", "comment");
        sel(doc, "article:has(> ::comment, section ::comment)", "comment", "deepComment");

        // hasSiblingAlternatives
        for (String query : new String[]{"#a:has(+ div, > missing)", "#a:has(> missing, + div)"}) {
            doc = Jsoup.parse("<div id=a></div><div><span></span></div>");
            sel(doc, "#a:has(+ div)", "a");
            sel(doc, query, "a");
        }

        // hasSiblingDescendant
        for (String query : new String[]{"#a:has(+ div span)", "#a:has(+ div > span)", "#a:has(~ div span)"}) {
            doc = Jsoup.parse("<div id=a></div><div><span></span></div>");
            sel(doc, query, "a");
        }
        for (String query : new String[]{"#a:has(+ div span)", "#a:has(~ div span)"}) {
            doc = Jsoup.parse("<div id=a></div><div><section><span></span></section></div>");
            sel(doc, query, "a");
        }
        for (String query : new String[]{"#a:has(+ div > span)", "#a:has(~ div > span)"}) {
            doc = Jsoup.parse("<div id=a></div><div><section><span></span></section></div>");
            sel(doc, query);
        }

        // hasAdjacentSiblingNotLaterSibling
        doc = Jsoup.parse("<div id=a></div><section></section><div><span></span></div>");
        sel(doc, "#a:has(+ div span)");
        // hasLaterSiblingDescendant
        sel(doc, "#a:has(~ div span)", "a");

        // hasSiblingDescendantNotSelfOrPrevious
        for (String html : new String[]{
            "<div><span></span></div><div id=a></div><div></div>",
            "<div id=a><span></span></div><div></div>"}) {
            doc = Jsoup.parse(html);
            sel(doc, "#a:has(+ div span)");
            sel(doc, "#a:has(+ div > span)");
            sel(doc, "#a:has(~ div span)");
        }

        // hasSeparateBranchScopes
        doc = Jsoup.parse("<div id=a></div><div><span></span></div>");
        sel(doc, "#a:has(+ div.missing, span)");
        sel(doc, "#a:has(span, + div.missing)");
        sel(doc, "#a:has(+ div:is(:has(span)), > missing)", "a");
        sel(doc, "#a:has(+ div:not(:has(missing)), > missing)", "a");
        sel(doc, "#a:has(div:has(+ span))");

        // hasSiblingContinuation
        doc = Jsoup.parse("<div id=a></div><div></div><section><span></span></section>");
        sel(doc, "#a:has(+ div + section)", "a");
        sel(doc, "#a:has(+ div + section span)", "a");
        sel(doc, "#a:has(+ div span)");

        // hasSiblingNodes
        doc = Jsoup.parse("<div id=a></div>text<!--between--><div><!--inside--></div>");
        sel(doc, "#a:has(+ div)", "a");
        sel(doc, "#a:has(+ ::comment)", "a");
        sel(doc, "#a:has(~ ::comment)", "a");
        sel(doc, "#a:has(+ div ::comment)", "a");
        sel(doc, "#a:has(+ div > ::comment)", "a");
        sel(doc, "#a:has(> ::comment)");

        // hasCompiledBranches (thread-safety + identity of results)
        String query = "div:has(+ div span, > a)";
        Evaluator evaluator = Selector.evaluatorOf(query);
        Evaluator combined = new CombiningEvaluator.And(new Evaluator.Id("a"), evaluator);
        final boolean[] ok = {true};
        IntStream.range(0, 8).parallel().forEach(i -> {
            Document d = Jsoup.parse("<div id=a></div><div><span></span></div><div id=b><a></a></div>");
            if (!ids(d.select(query)).equals(ids(d.select(evaluator)))) ok[0] = false;
            if (!ids(d.select(evaluator)).equals("a,b")) ok[0] = false;
            if (d.selectFirst(query) != d.selectFirst(evaluator)) ok[0] = false;
            if (!ids(d.select(combined)).equals("a")) ok[0] = false;
            if (!d.getElementById("a").is(combined)) ok[0] = false;
            if (d.getElementById("a").closest(combined) != d.getElementById("a")) ok[0] = false;
            if (!Jsoup.parse("<div id=a></div>").select(evaluator).isEmpty()) ok[0] = false;
        });
        if (ok[0]) pass++; else { fail++; System.out.println("FAIL hasCompiledBranches"); }

        // notMatchesNodeValues (::comment:not(...))
        doc = Jsoup.parse("<p><!--foo--><!--bar--><!--baz--></p>");
        String n1 = doc.selectNodes("::comment:not(:contains(foo))", org.jsoup.nodes.Comment.class)
            .stream().map(org.jsoup.nodes.Comment::getData).reduce("", (a,b)->a+b);
        if (n1.equals("barbaz")) pass++; else { fail++; System.out.println("FAIL notComments: " + n1); }
        String n2 = doc.selectNodes("::comment:not(:matches(^ba))", org.jsoup.nodes.Comment.class)
            .stream().map(org.jsoup.nodes.Comment::getData).reduce("", (a,b)->a+b);
        if (n2.equals("foo")) pass++; else { fail++; System.out.println("FAIL notComments2: " + n2); }
        String n3 = doc.selectNodes("::comment:not(:contains(foo), :contains(bar))", org.jsoup.nodes.Comment.class)
            .stream().map(org.jsoup.nodes.Comment::getData).reduce("", (a,b)->a+b);
        if (n3.equals("baz")) pass++; else { fail++; System.out.println("FAIL notComments3: " + n3); }
        // nestedNodeSelectorKeepsOuterContext
        String n4 = doc.selectNodes("::comment:not(::text):contains(foo)", org.jsoup.nodes.Comment.class)
            .stream().map(org.jsoup.nodes.Comment::getData).reduce("", (a,b)->a+b);
        if (n4.equals("foo")) pass++; else { fail++; System.out.println("FAIL nestedNode: " + n4); }

        // notRequiresNonEmptySelector
        for (String q : new String[]{"p:not()", "p:not( )"}) {
            try { Selector.evaluatorOf(q); fail++; System.out.println("FAIL not-empty: " + q); }
            catch (Selector.SelectorParseException e) {
                if (":not(selector) subselect must not be empty".equals(e.getMessage())) pass++;
                else { fail++; System.out.println("FAIL not-empty msg: " + e.getMessage()); }
            }
        }

        System.out.println("\nPASS=" + pass + " FAIL=" + fail);
        if (fail > 0) System.exit(1);
    }
}

