import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.select.Elements;
import org.jsoup.select.Selector;

import java.util.ArrayList;
import java.util.List;

public class Diff {
    static int same = 0, diffs = 0, errors = 0;

    static String run(Document d, String css) {
        try {
            Elements els = d.select(css);
            StringBuilder sb = new StringBuilder("OK:");
            for (Element e : els) {
                sb.append('<').append(e.tagName()).append("#").append(e.id()).append(">");
            }
            return sb.toString();
        } catch (Selector.SelectorParseException e) {
            return "PARSE_EX";
        } catch (Exception e) {
            return "OTHER_EX:" + e.getClass().getSimpleName();
        }
    }

    static void t(String html, String css) {
        try {
            Document d1 = Jsoup.parse(html);
            Document d2 = Jsoup.parse(html);
            String a = run(d1, css);
            String b = run(d2, css);
            if (a.equals(b)) same++;
            else {
                diffs++;
                System.out.println("DIFF css=" + css + "\n  html=" + html + "\n  ours=" + a + "\n  up  =" + b);
            }
        } catch (Throwable t) {
            errors++;
            System.out.println("ERROR css=" + css + " : " + t);
        }
    }

    public static void main(String[] args) {
        String[][] cases = {
            // descendant / child / sibling
            {"<div id=a><div id=b><span id=s></span></div></div>", "div:has(span)"},
            {"<div id=a><div id=b><span id=s></span></div></div>", "div:has(> span)"},
            {"<div id=a><div id=b><span id=s></span></div></div>", "#a:has(> #s)"},
            {"<div id=outer class=x><div id=inner class=x></div></div>", "div.x:has(div.x)"},
            {"<ul><li id=l1><p id=p1></p></li><li id=l2></li><li id=l3><p id=p3></p></li></ul>", "li:has(+ li p)"},
            {"<ul><li id=l1><p id=p1></p></li><li id=l2></li><li id=l3><p id=p3></p></li></ul>", "li:has(~ li p)"},
            {"<ul><li id=l1></li><li id=l2></li><li id=l3></li></ul>", "li:has(+ li)"},
            {"<ul><li id=l1></li><li id=l2></li><li id=l3></li></ul>", "li:has(~ li)"},
            {"<div id=d1><h1></h1></div><div id=d2><h2></h2></div>", "div:has(h1 ~ h2)"},
            {"<div id=d><h1></h1><h2></h2></div>", "div:has(h1 + h2)"},
            // branches
            {"<ul><li id=a></li><li id=b><a></a></li><li id=c><span></span></li><li id=d></li></ul>", "li:has(+ li, a)"},
            {"<ul><li id=a></li><li id=b><a></a></li><li id=c><span></span></li><li id=d></li></ul>", "li:has(> a, + li span)"},
            {"<ul><li id=a></li><li id=b><a></a></li><li id=c><span></span></li><li id=d></li></ul>", "li:has(~ li a, + li)"},
            {"<ul><li id=a></li><li id=b><a></a></li><li id=c><span></span></li></ul>", "li:has( a , span )"},
            // nested has / scope
            {"<div id=d><p></p><section id=s><a></a></section></div>", "div:has(section:has(+ p))"},
            {"<div id=d><section id=s></section><p id=p></p></div>", "div:has(section:has(+ p))"},
            {"<div id=d><section id=s><b></b></section><p></p></div>", "div:has(section:has(b):has(+ p))"},
            {"<div id=d><section id=s></section></div><p id=p></p>", "div:has(section:has(+ p))"},
            {"<section id=sec><div id=d><a id=a></a></div></section>", "section:has(div:has(:scope > a))"},
            {"<div id=d><a></a><span></span></div>", "#d:has(:scope > a)"},
            {"<div id=d1></div><div id=d2></div>", "#d1:has(:scope + div)"},
            {"<div id=x><p></p></div>", "div:has(:scope)"},
            // is / not
            {"<div id=d><p></p><span></span></div>", "div:has(:is(p, span))"},
            {"<div id=d><p></p><a></a></div>", "div:has(:is(p) + a)"},
            {"<div id=d></div><p></p>", "div:has(:is(div) + p)"},
            {"<div id=a><p></p></div><div id=b></div>", "div:not(:has(p))"},
            {"<div id=x><p class=z></p></div><div id=y><p></p></div>", "div:has(p:not(.z))"},
            // quoted/escaped
            {"<div id=d><p data-x=\"a b\"></p></div>", "div:has(p[data-x='a b'])"},
            {"<div class=\"a.b\" id=x><i class=\"c.d\"></i></div>", ".a\\.b:has(.c\\.d)"},
            // leaves
            {"<div id=d><!-- hi --><p></p></div><div id=e><p></p></div>", "div:has(::comment)"},
            {"<div id=d><p></p><!-- c --><span></span></div>", "div:has(p + ::comment)"},
            {"<div id=d><p></p><!-- c --><span></span></div>", "div:has(p + span)"},
            {"<div id=d><p></p><!-- c --><span></span></div>", "div:has(::comment + span)"},
            {"<div id=d></div>x<p id=p></p>", "div:has(+ p ::comment)"},
            {"<article id=a><h1></h1>x<p></p></article>", "article:has(h1 + p:not(::comment))"},
            {"<article id=a><h1></h1><!--x--><p></p></article>", "article:has(h1 + p:not(::text))"},
            {"<article id=a><h1></h1>x<!--c--></article>", "article:has(h1 + ::comment)"},
            {"<article id=a></article>x<p></p>", "article:has(+ p:not(::comment))"},
            {"<article id=a><h1></h1>x<p></p></article>", "article:has(h1 + p:is(:not(::comment)))"},
            {"<article id=a><h1></h1><!--c--></article>", "article:has(h1 + :is(::comment))"},
            {"<article id=a><h1></h1>x<!--c--></article>", "article:has(h1 + :is(::comment))"},
            {"<div id=a></div><!--c-->", "#a:has(+ :is(::comment))"},
            {"<div id=a></div>x<!--c-->", "#a:has(+ :is(::comment))"},
            {"<article id=a><h1></h1><p></p></article>", "article:has(h1 + :is(::comment, p))"},
            {"<div id=a></div><!--c-->", "#a:has(+ :not(::text))"},
            {"<article id=a></article><!--c--><b></b>x<i></i>", "article:has(+ ::comment + b + i)"},
            {"<article id=a></article><!--c--><b></b><i></i>", "article:has(+ ::comment + b + i)"},
            {"<article id=a><div><h1></h1>x<!--c--></div></article>", "article:has(div:is(h1 + ::comment))"},
            {"<article id=a><div><h1></h1><!--c--></div></article>", "article:has(div:is(h1 + ::comment))"},
            // gap leaves at leading sibling
            {"<div id=a></div>x<div><!--inside--></div>", "#a:has(+ div > ::comment)"},
            {"<div id=a></div>x<div><span></span></div>", "#a:has(+ div span)"},
            {"<div id=a></div>text<!--c-->", "#a:has(+ ::comment)"},
            {"<div id=a></div><b></b>x<i></i>", "#a:has(+ b + i)"},
            {"<div id=a></div><div><h1></h1><!--c--><b></b></div>", "#a:has(+ div h1 + ::comment + b)"},
            {"<div id=a></div><div><h1></h1>x<!--c--><b></b></div>", "#a:has(+ div h1 + ::comment + b)"},
            // #2610 battery
            {"<div id=empty></div><div id=child><a href=x></a></div><div id=deep><section><a href=x></a></section></div>", "div:has(> a[href])"},
            {"<div id=empty></div><div id=child><a href=x></a></div><div id=deep><section><a href=x></a></section></div>", "div:has(> missing)"},
            {"<div id=deep><section><a href=x></a></section></div>", "div:has(> section a)"},
            {"<div id=deep><section><a href=x></a></section></div>", "div:has(> section > a)"},
            {"<div id=early><a href=x></a><span></span></div><div id=late><section></section><span></span></div><div id=deep><section><span></span></section></div>", "div:has(> a[href], > span)"},
            {"<div id=early><a href=x></a><span></span></div><div id=late><section></section><span></span></div><div id=deep><section><span></span></section></div>", "div:has(> a[href], span)"},
            {"<article id=nested><div><section><a></a></section></div></article><article id=span><span></span></article><article id=deep><section><span></span></section></article>", "article:has(> div:has(a), > span)"},
            {"<article id=span><span></span></article><article id=comment>text<!--direct--></article><article id=deepComment><section><!--deep--></section></article>", "article:has(> ::comment)"},
            {"<article id=span><span></span></article><article id=comment>text<!--direct--></article><article id=deepComment><section><!--deep--></section></article>", "article:has(> span, > ::comment)"},
            {"<article id=comment>text<!--direct--></article><article id=deepComment><section><!--deep--></section></article>", "article:has(> ::comment, section ::comment)"},
            {"<div id=a></div><div><span></span></div>", "#a:has(+ div, > missing)"},
            {"<div id=a></div><div><span></span></div>", "#a:has(> missing, + div)"},
            {"<div id=a></div><div><span></span></div>", "#a:has(+ div span)"},
            {"<div id=a></div><div><span></span></div>", "#a:has(+ div > span)"},
            {"<div id=a></div><div><span></span></div>", "#a:has(~ div span)"},
            {"<div id=a></div><div><section><span></span></section></div>", "#a:has(+ div span)"},
            {"<div id=a></div><div><section><span></span></section></div>", "#a:has(~ div span)"},
            {"<div id=a></div><div><section><span></span></section></div>", "#a:has(+ div > span)"},
            {"<div id=a></div><div><section><span></span></section></div>", "#a:has(~ div > span)"},
            {"<div id=a></div><section></section><div><span></span></div>", "#a:has(+ div span)"},
            {"<div id=a></div><section></section><div><span></span></div>", "#a:has(~ div span)"},
            {"<div><span></span></div><div id=a></div><div></div>", "#a:has(+ div span)"},
            {"<div id=a><span></span></div><div></div>", "#a:has(+ div span)"},
            {"<div id=a></div><div><span></span></div>", "#a:has(+ div.missing, span)"},
            {"<div id=a></div><div><span></span></div>", "#a:has(span, + div.missing)"},
            {"<div id=a></div><div><span></span></div>", "#a:has(+ div:is(:has(span)), > missing)"},
            {"<div id=a></div><div><span></span></div>", "#a:has(+ div:not(:has(missing)), > missing)"},
            {"<div id=a></div><div><span></span></div>", "#a:has(div:has(+ span))"},
            {"<div id=a></div><div></div><section><span></span></section>", "#a:has(+ div + section)"},
            {"<div id=a></div><div></div><section><span></span></section>", "#a:has(+ div + section span)"},
            {"<div id=a></div><div></div><section><span></span></section>", "#a:has(+ div span)"},
            {"<div id=a></div>text<!--between--><div><!--inside--></div>", "#a:has(+ div)"},
            {"<div id=a></div>text<!--between--><div><!--inside--></div>", "#a:has(+ ::comment)"},
            {"<div id=a></div>text<!--between--><div><!--inside--></div>", "#a:has(~ ::comment)"},
            {"<div id=a></div>text<!--between--><div><!--inside--></div>", "#a:has(+ div ::comment)"},
            {"<div id=a></div>text<!--between--><div><!--inside--></div>", "#a:has(+ div > ::comment)"},
            {"<div id=a></div>text<!--between--><div><!--inside--></div>", "#a:has(> ::comment)"},
            // syntax errors
            {"<div id=d><p>x</p></div>", "div:has(,)"},
            {"<div id=d><p>x</p></div>", "div:has(p,,q)"},
            {"<div id=d><p>x</p></div>", "div:has( ,p)"},
