            {"<article id=a>hello</article><article id=b><p>x</p></article>", "article:has(> ::text)"},
            {"<article id=a></article>x<p></p>", "article:has(+ ::text, + p)"},
            {"<article id=a></article><p></p><div><b><!--c--></b></div>", "article:has(~ div ::comment)"},
