import org.jsoup.select.*;
import java.lang.reflect.Field;
import java.util.List;

public class TreeDump {
    static String q;
    static void walk(Object o, String indent) {
        if (o == null) return;
        Class<?> c = o.getClass();
        String name = c.getSimpleName();
        String extra = "";
        try {
            if (o instanceof StructuralEvaluator) {
                Field wn = StructuralEvaluator.class.getDeclaredField("wantsNodes");
                wn.setAccessible(true);
                extra = " wantsNodes=" + wn.get(o);
                Field ev = StructuralEvaluator.class.getDeclaredField("evaluator");
                ev.setAccessible(true);
                Object child = ev.get(o);
                if (o instanceof StructuralEvaluator.ImmediateParentRun) {
                    Field es = StructuralEvaluator.ImmediateParentRun.class.getDeclaredField("evaluators");
                    es.setAccessible(true);
                    List<?> list = (List<?>) es.get(o);
                    System.out.println(indent + name + extra + " strictRun=" + getBool(o, "strictRoot"));
                    for (Object x : list) walk(x, indent + "  ");
                    return;
                }
                System.out.println(indent + name + extra + (getBool(o,"strictRoot")?" strictRoot":""));
                walk(child, indent + "  ");
                return;
