import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.select.Selector;

public class FuzzEmit {
    static String parseResult(String css) {
        try {
            Selector.evaluatorOf(css);
            return "ACCEPT";
        } catch (Selector.SelectorParseException e) {
            return "REJECT";
        } catch (Exception e) {
            return "OTHER:" + e.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        String[] malformed = {
            // empty / whitespace
            "div:has()", "div:has( )", "div:has(  )", "div:has(\t)", "div:has(\n)",
            ":has()", ":has( )",
            // dangling combinators
            "div:has(>)", "div:has(+)", "div:has(~)", "div:has( >)", "div:has( +)", "div:has( ~)",
            "div:has(> )", "div:has(+ )", "div:has(~ )", "div:has( > )",
            "div:has(p>)", "div:has(p+)", "div:has(p~)", "div:has(p >)", "div:has(p +)", "div:has(p ~)",
            "div:has(p > )", "div:has(p >> q)", "div:has(p + + q)", "div:has(p ~ ~ q)",
            "div:has(> > p)", "div:has(+ + p)",
            // empty comma branches
            "div:has(,)", "div:has(p,)", "div:has(,p)", "div:has(p,,q)", "div:has(p, ,q)",
            "div:has( p , )", "div:has( , p)", "div:has(p, q,)",
            // unbalanced parens
            "div:has(p", "div:has((p)", "div:has(p))", "div:has(p:has(q)", "div:has(p:has(q))",
            "div:has(p:has())", "div:has(:has(p))", "div:has(p:has(>)",
            // bogus simple selectors
            "div:has(.)", "div:has(#)", "div:has([)", "div:has([])", "div:has([a=)",
            "div:has(::)", "div:has(::nope)", "div:has(p:)", "div:has(:)", "div:has(p::9)",
            "div:has(@)", "div:has(%)", "div:has(p q +)", "div:has(+ p +)",
            // not / is empty
            "div:has(p:not())", "div:has(p:not( ))", "div:has(:is())", "div:has(:is( ))",
            "p:not()", "p:not( )", ":is()",
            // bad pseudo args
            "div:has(p:lt())", "div:has(p:eq(x))", "div:has(p:contains())",
            // good branch must not rescue bad branch (outer and inner)
            "div:has(p), div:has(>)", "div:has(>), div:has(p)", "div:has(p, >)", "div:has(>, p)",
            "div:has(p, q, +)", "div:has(p + , q)",
            // trailing junk
            "div:has(p) q)", "div:has(p))", ":has(p))", "div:has(p) +",
            // attributes malformed
            "div:has([a b])", "div:has([a=])", "div:has([a=\"unclosed])",
        };
        int n = 0;
        for (String css : malformed) System.out.println(n++ + "\t" + css + "\t" + parseResult(css));

        System.out.println("---VALID---");
        String[] valid = {
            "div:has(p)", "div:has( p )", "div:has(>p)", "div:has(> p)", "div:has(+p)", "div:has(~p)",
            "div:has(p, q)", "div:has( p , q )", "div:has(p:has(q))", "div:has(:scope > p)",
            "div:has(p:not(.x))", "div:has(:is(p, q))", "div:has(*)", "div:has(> *)",
            "div:has(p[a])", "div:has(p[a='x'])", "div:has(.a\\.b)", "div:has(p + q)", "div:has(p ~ q)",
            "div:has(> p + q)", "div:has(::comment)", "div:has(p, )".replace(", )", ")"),
        };
        for (String css : valid) System.out.println(css + "\t" + parseResult(css));
    }
}

