import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.select.Elements;
import org.jsoup.select.Selector;
import org.jsoup.select.Evaluator;

public class ProbeFinal {
    static int pass=0, fail=0;
    static String ids(Elements els){
        StringBuilder sb=new StringBuilder();
        for(Element e:els){if(sb.length()>0)sb.append(",");sb.append(e.id().isEmpty()?e.tagName():e.id());}
        return sb.toString();
    }
    static void ck(String name, String html, String css, String want){
        Document d=Jsoup.parse(html);
        String got=ids(d.select(css));
        if(got.equals(want))pass++;else{fail++;System.out.println("FAIL "+name+"\n  css="+css+"\n  want="+want+"\n  got ="+got);}
    }

