import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.select.Elements;
import org.jsoup.select.Selector;

import java.util.*;

public class FuzzRandom {
    static Random rnd;
    static final String[] TAGS = {"div", "p", "span", "a", "section", "ul", "li", "b", "i"};
    static final char[] COMB = {' ', '>', '+', '~'};
    static int idCounter;

    // build a random html tree; assign every element a unique id attr
    static void build(StringBuilder sb, int depth, Random r, java.util.function.IntSupplier ids) {
        int n = 1 + r.nextInt(3);
        for (int i = 0; i < n; i++) {
            String tag = TAGS[r.nextInt(TAGS.length)];
            int id = ids.getAsInt();
            sb.append('<').append(tag).append(" id=e").append(id);
            // occasional class / attr
            if (r.nextInt(3) == 0) sb.append(" class=c").append(r.nextInt(3));
            if (r.nextInt(4) == 0) sb.append(" data-v=").append(r.nextInt(3));
            sb.append('>');
            if (depth > 0 && r.nextInt(2) == 0) build(sb, depth - 1, r, ids);
            if (r.nextInt(3) == 0) sb.append("txt").append(r.nextInt(4));
            sb.append("</").append(tag).append('>');
        }
    }

    // generate a relative selector fragment (used inside :has), element-only
    static String rel(int depth, Random r, boolean allowComma) {
        StringBuilder sb = new StringBuilder();
        int branches = allowComma && r.nextInt(3) == 0 ? 2 : 1;
        for (int b = 0; b < branches; b++) {
            if (b > 0) sb.append(',');
            int steps = 1 + r.nextInt(3);
            if (r.nextInt(3) != 0) sb.append(comb(r)); // optional leading combinator
            for (int s = 0; s < steps; s++) {
                sb.append(simple(r, depth));
                if (s < steps - 1) sb.append(comb(r));
            }
        }
        return sb.toString();
    }

    static String comb(Random r) {
        char c = COMB[r.nextInt(COMB.length)];
        return c == ' ' ? " " : String.valueOf(c);
    }

    static String simple(Random r, int depth) {
        String s;
        switch (r.nextInt(7)) {
            case 0: s = "*"; break;
            case 1: s = TAGS[r.nextInt(TAGS.length)]; break;
            case 2: s = ".c" + r.nextInt(3); break;
            case 3: s = "[data-v=" + r.nextInt(3) + "]"; break;
            case 4: s = TAGS[r.nextInt(4)] + ".c" + r.nextInt(3); break;
            case 5: s = depth > 0 && r.nextInt(2) == 0 ? TAGS[r.nextInt(4)] + ":has(" + rel(depth - 1, r, true) + ")"
                                                       : TAGS[r.nextInt(4)]; break;
            default: s = depth > 0 && r.nextInt(3) == 0 ? TAGS[r.nextInt(4)] + ":not(" + rel(depth - 1, r, true) + ")"
                                                        : TAGS[r.nextInt(4)];
        }
        // occasionally wrap in :is
        if (depth > 0 && r.nextInt(6) == 0) s = ":is(" + rel(depth - 1, r, true) + ")";
        return s;
    }

    static String select(String html, String css) {
        try {
            Document d = Jsoup.parse(html);
            Elements els = d.select(css);
            List<String> ids = new ArrayList<>();
            for (Element e : els) ids.add(e.id());
            Collections.sort(ids);
            return "OK:" + ids;
        } catch (Selector.SelectorParseException e) {
