    static String rel(int depth, Random r, boolean allowComma) {
        StringBuilder sb = new StringBuilder();
        int branches = allowComma && r.nextInt(3) == 0 ? 2 : 1;
        for (int b = 0; b < branches; b++) {
            if (b > 0) sb.append(',');
            int steps = 1 + r.nextInt(3);
            if (r.nextInt(3) != 0) sb.append(comb(r)); // optional leading combinator
            for (int s = 0; s < steps; s++) {
                sb.append(simple(r, depth));
                if (s < steps - 1) sb.append(comb(r));
            }
        }
        return sb.toString();
    }

    static String comb(Random r) {
        char c = COMB[r.nextInt(COMB.length)];
        return c == ' ' ? " " : String.valueOf(c);
    }

    static String simple(Random r, int depth) {
        String s;
        switch (r.nextInt(7)) {
            case 0: s = "*"; break;
            case 1: s = TAGS[r.nextInt(TAGS.length)]; break;
            case 2: s = ".c" + r.nextInt(3); break;
            case 3: s = "[data-v=" + r.nextInt(3) + "]"; break;
            case 4: s = TAGS[r.nextInt(4)] + ".c" + r.nextInt(3); break;
            case 5: s = depth > 0 && r.nextInt(2) == 0 ? TAGS[r.nextInt(4)] + ":has(" + rel(depth - 1, r, true) + ")"
                                                       : TAGS[r.nextInt(4)]; break;
            default: s = depth > 0 && r.nextInt(3) == 0 ? TAGS[r.nextInt(4)] + ":not(" + rel(depth - 1, r, true) + ")"
                                                        : TAGS[r.nextInt(4)];
        }
        // occasionally wrap in :is
        if (depth > 0 && r.nextInt(6) == 0) s = ":is(" + rel(depth - 1, r, true) + ")";
        return s;
    }

    static String select(String html, String css) {
        try {
            Document d = Jsoup.parse(html);
            Elements els = d.select(css);
            List<String> ids = new ArrayList<>();
            for (Element e : els) ids.add(e.id());
            Collections.sort(ids);
            return "OK:" + ids;
        } catch (Selector.SelectorParseException e) {
            return "PE";
        } catch (Exception e) {
            return "EX:" + e.getClass().getSimpleName() + ":" + e.getMessage();
        }
    }

    public static void main(String[] args) {
        long seed = args.length > 0 ? Long.parseLong(args[0]) : new Random().nextLong();
        int iters = args.length > 1 ? Integer.parseInt(args[1]) : 3000;
        rnd = new Random(seed);
        int[] idBox = {0};
        for (int it = 0; it < iters; it++) {
            Random r = new Random(rnd.nextLong());
            idBox[0] = 0;
            StringBuilder hb = new StringBuilder();
            build(hb, 3, r, () -> idBox[0]++);
            String html = hb.toString();
            String inner = rel(2, r, true);
            String subject = TAGS[r.nextInt(TAGS.length)];
            String css = subject + ":has(" + inner + ")";
            if (r.nextInt(3) == 0) css += ", " + TAGS[r.nextInt(TAGS.length)] + ":has(" + rel(2, r, false) + ")";
            System.out.println(it + "\t" + select(html, css));
        }
    }
}

